compilerv1Parser::compilerv1Parser(TokenStream *input) : compilerv1Parser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

compilerv1Parser::compilerv1Parser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  compilerv1Parser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *compilerv1ParserStaticData->atn, compilerv1ParserStaticData->decisionToDFA, compilerv1ParserStaticData->sharedContextCache, options);
}

compilerv1Parser::~compilerv1Parser() {
  delete _interpreter;
}

const atn::ATN& compilerv1Parser::getATN() const {
  return *compilerv1ParserStaticData->atn;
}

std::string compilerv1Parser::getGrammarFileName() const {
  return "compilerv1.g4";
}

const std::vector<std::string>& compilerv1Parser::getRuleNames() const {
  return compilerv1ParserStaticData->ruleNames;
}

